  async function directAuth(){if(state.directAuthPromise)return state.directAuthPromise;state.directAuthPromise=(async()=>{const config=await fetchJson('/api/founder-profile/auth-config',{cache:'no-store'},false);if(!config?.enabled)return null;const [{initializeApp,getApps},{getAuth,setPersistence,browserLocalPersistence}]=await Promise.all([import('https://www.gstatic.com/firebasejs/11.10.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/11.10.0/firebase-auth.js')]);const app=getApps().find(item=>item.name==='nyx-founder-owner')||initializeApp({apiKey:config.apiKey,authDomain:`${config.projectId}.firebaseapp.com`,projectId:config.projectId},'nyx-founder-owner');const auth=getAuth(app);try{await setPersistence(auth,browserLocalPersistence)}catch{}if(typeof auth.authStateReady==='function')await auth.authStateReady();return auth})();try{return await state.directAuthPromise}catch(error){state.directAuthPromise=null;throw error}}
