  async function attachmentUrl(attachment){if(state.blobUrls.has(attachment.id))return state.blobUrls.get(attachment.id);if(state.blobPromises.has(attachment.id))return state.blobPromises.get(attachment.id);const promise=(async()=>{const token=await accountToken();const response=await fetch(attachment.url,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)throw new Error('Attachment unavailable.');const url=URL.createObjectURL(await response.blob());state.blobUrls.set(attachment.id,url);state.blobPromises.delete(attachment.id);return url})().catch(error=>{state.blobPromises.delete(attachment.id);throw error});state.blobPromises.set(attachment.id,promise);return promise}
  function unlockDmSound(){if(state.audioUnlocked)return;try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return;state.audioContext=state.audioContext||new AudioContext();void state.audioContext.resume();state.audioUnlocked=true}catch{}}
  function playChatPing(notificationId,kind='chat'){if(state.notifiedDm.has(notificationId))return;state.notifiedDm.add(notificationId);if(state.notifiedDm.size>200)state.notifiedDm.delete(state.notifiedDm.values().next().value);if(window.parent!==window){window.parent.postMessage({type:'nyx:chat-notification',notificationId:String(notificationId).slice(0,180),kind:kind==='mention'?'mention':'dm'},location.origin);return}const context=state.audioContext;if(!state.audioUnlocked||!context)return;try{void context.resume();const now=context.currentTime;[0,0.105].forEach((offset,index)=>{const oscillator=context.createOscillator();const gain=context.createGain();oscillator.type='sine';oscillator.frequency.setValueAtTime(index?740:620,now+offset);gain.gain.setValueAtTime(0.0001,now+offset);gain.gain.exponentialRampToValueAtTime(0.09,now+offset+0.012);gain.gain.exponentialRampToValueAtTime(0.0001,now+offset+0.12);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(now+offset);oscillator.stop(now+offset+0.13)})}catch{}}
