  async function refreshConversations(){const payload=await fetchJson(`${API}/conversations`,{cache:'no-store'});mergeConversations(Array.isArray(payload.conversations)?payload.conversations:[],{notify:true});const activity=payload.channelActivity&&typeof payload.channelActivity==='object'?payload.channelActivity:{};Object.entries(activity).forEach(([channel,value])=>{const timestamp=Number(value?.lastMessageAtMs||0);const previous=Number(state.latestActivity[channel]||0);if(timestamp>previous&&value?.lastMessageAuthorUid&&value.lastMessageAuthorUid!==state.me?.uid&&mentionsMe(value.lastMessageText))playChatPing(`mention:${channel}:${timestamp}`,'mention');state.latestActivity[channel]=Math.max(previous,timestamp)});renderChannels()}

  function renderChannels(){refs.channelList.replaceChildren();state.channels.forEach(channel=>{const button=document.createElement('button');button.type='button';button.className=`channel-button${state.active.type==='channel'&&channel.id===state.active.id?' active':''}`;const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');const use=document.createElementNS('http://www.w3.org/2000/svg','use');use.setAttribute('href','#icon-hash');icon.append(use);const label=document.createElement('span');label.textContent=channel.name;const dot=document.createElement('i');dot.setAttribute('aria-hidden','true');button.append(icon,label,dot);const key=`channel:${channel.id}`;button.classList.toggle('unread',key!==scopeKey()&&Number(state.latestActivity[channel.id]||0)>Number(state.lastRead[key]||0));button.addEventListener('click',()=>void switchScope({type:'channel',id:channel.id}));refs.channelList.append(button)})}
