  async function applyVoiceState(payload){if(Array.isArray(payload?.channels))state.voiceChannels=payload.channels;if(Array.isArray(payload?.participants))state.voiceParticipants=payload.participants;if(state.voiceSessionId&&payload?.joined===false){await leaveVoice({notifyServer:false});showNotice('Your voice session ended. Join the channel again.');return}if(state.voiceChannelId){const active=state.voiceParticipants.filter(participant=>participant.channelId===state.voiceChannelId&&participant.uid!==state.me?.uid);const activeUids=new Set(active.map(participant=>participant.uid));[...state.voicePeers.keys()].filter(uid=>!activeUids.has(uid)).forEach(closeVoicePeer);active.forEach(participant=>ensureVoicePeer(participant,String(state.me?.uid||'').localeCompare(participant.uid)<0));for(const signal of Array.isArray(payload?.signals)?payload.signals:[])await handleVoiceSignal(signal)}renderVoiceChannels()}
