  async function joinVoice(channelId){if(state.voiceBusy||state.voiceChannelId===channelId)return;if(!window.RTCPeerConnection||!navigator.mediaDevices?.getUserMedia){showNotice('Voice channels are not supported by this browser.');return}state.voiceBusy=true;try{if(state.voiceSessionId)await leaveVoice();const stream=await navigator.mediaDevices.getUserMedia({video:false,audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});const sessionId=(crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}-${Math.random().toString(36).slice(2)}`).replace(/[^A-Za-z0-9_-]/g,'');state.voiceStream=stream;state.voiceSessionId=sessionId;state.voiceChannelId=channelId;state.voiceMuted=false;state.voiceDeafened=false;const payload=await fetchJson(`${API}/voice/join`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channelId,sessionId})});await applyVoiceState(payload);scheduleVoicePoll(VOICE_POLL_MS);closeDrawers();showNotice(`Joined ${state.voiceChannels.find(item=>item.id===channelId)?.name||'voice channel'}.`,'success')}catch(error){state.voiceStream?.getTracks().forEach(track=>track.stop());state.voiceStream=null;state.voiceSessionId='';state.voiceChannelId='';closeAllVoicePeers();renderVoiceChannels();if(error.name==='NotAllowedError')showNotice('Allow microphone access to join a voice channel.');else showNotice(error.message||'The voice channel could not be joined.')}finally{state.voiceBusy=false}}
  async function leaveVoice({notifyServer=true,resumePolling=true}={}){const sessionId=state.voiceSessionId;clearTimeout(state.voicePollTimer);state.voicePollTimer=0;state.voiceSessionId='';state.voiceChannelId='';state.voiceMuted=false;state.voiceDeafened=false;closeAllVoicePeers();state.voiceStream?.getTracks().forEach(track=>track.stop());state.voiceStream=null;state.voiceParticipants=state.voiceParticipants.filter(participant=>participant.uid!==state.me?.uid);renderVoiceChannels();if(notifyServer&&sessionId){try{await fetchJson(`${API}/voice/leave`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId})})}catch{}}if(resumePolling&&state.me)scheduleVoicePoll(5000)}
  function toggleVoiceMute(){if(!state.voiceStream)return;state.voiceMuted=!state.voiceMuted;state.voiceStream.getAudioTracks().forEach(track=>{track.enabled=!state.voiceMuted});updateVoicePanel()}
