  function openMember(member){refs.memberDialogContent.replaceChildren();const banner=document.createElement('div');banner.className='member-card-banner';const body=document.createElement('div');body.className='member-card-body';body.append(avatarElement(member,member.online));const name=document.createElement('h2');name.textContent=member.displayName;const handle=document.createElement('p');handle.textContent=member.handle;const facts=document.createElement('div');facts.className='member-card-facts';const role=document.createElement('span');role.textContent=member.roleLabel||roleLabel(member.role);const status=document.createElement('span');status.className=member.online?'online':'offline';status.textContent=member.online?'Online':'Offline';facts.append(role,status);body.append(name,handle,facts);if(!member.self){const dm=document.createElement('button');dm.type='button';dm.className='member-dm-button';dm.textContent='Message privately';dm.addEventListener('click',()=>void startDm(member));body.append(dm)}refs.memberDialogContent.append(banner,body);refs.memberDialog.showModal();closeDrawers()}
