  function renderDmPicker(search=''){const value=String(search).trim().toLowerCase();refs.dmPickerList.replaceChildren();state.members.filter(member=>!member.self&&(!value||`${member.displayName} ${member.handle}`.toLowerCase().includes(value))).forEach(member=>{const button=document.createElement('button');button.type='button';button.className='member-button';button.append(avatarElement(member,member.online));const copy=document.createElement('span');const name=document.createElement('strong');name.textContent=member.displayName;const detail=document.createElement('small');detail.textContent=`${member.handle} · ${member.roleLabel||roleLabel(member.role)}`;copy.append(name,detail);button.append(copy);button.addEventListener('click',()=>void startDm(member));refs.dmPickerList.append(button)})}
